// Simple Cosmic Courier game
// Canvas with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  canvas.width = canvas.clientWidth || 800;
  canvas.height = canvas.clientHeight || 600;

  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  const player = {
    x: canvas.width / 2,
    y: canvas.height - 50,
    r: 12,
    speed: 2,
    boostSpeed: 5,
    fuel: 100,
    boost: false,
  };

  const asteroids = [];
  const packages = [];
  let gameOver = false;
  let score = 0;

  function rand(min, max) { return Math.random() * (max - min) + min; }
  function spawnAsteroid() {
    const size = rand(10, 30);
    asteroids.push({
      x: rand(0, canvas.width),
      y: -size,
      r: size,
      vy: rand(1, 3),
    });
  }
  function spawnPackage() {
    const size = 8;
    packages.push({
      x: rand(0, canvas.width),
      y: -size,
      r: size,
      vy: rand(1, 2),
    });
  }

  function update() {
    if (gameOver) return;
    // Player movement
    const moving = {x: 0, y: 0};
    if (keys['ArrowLeft']) moving.x -= 1;
    if (keys['ArrowRight']) moving.x += 1;
    if (keys['ArrowUp']) moving.y -= 1;
    if (keys['ArrowDown']) moving.y += 1;
    const norm = Math.hypot(moving.x, moving.y) || 1;
    const spd = (keys[' '] && player.fuel > 0) ? player.boostSpeed : player.speed;
    player.boost = keys[' '] && player.fuel > 0;
    if (player.boost) player.fuel = Math.max(0, player.fuel - 0.3);
    player.x += (moving.x / norm) * spd;
    player.y += (moving.y / norm) * spd;
    // Keep inside canvas
    player.x = Math.max(player.r, Math.min(canvas.width - player.r, player.x));
    player.y = Math.max(player.r, Math.min(canvas.height - player.r, player.y));

    // Spawn entities
    if (Math.random() < 0.02) spawnAsteroid();
    if (Math.random() < 0.01) spawnPackage();

    // Move asteroids & packages
    asteroids.forEach(a => a.y += a.vy);
    packages.forEach(p => p.y += p.vy);
    // Remove off‑screen
    while (asteroids.length && asteroids[0].y - asteroids[0].r > canvas.height) asteroids.shift();
    while (packages.length && packages[0].y - packages[0].r > canvas.height) packages.shift();

    // Collision detection
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      const dx = a.x - player.x, dy = a.y - player.y;
      if (Math.hypot(dx, dy) < a.r + player.r) { gameOver = true; break; }
    }
    for (let i = packages.length - 1; i >= 0; i--) {
      const p = packages[i];
      const dx = p.x - player.x, dy = p.y - player.y;
      if (Math.hypot(dx, dy) < p.r + player.r) { score++; packages.splice(i, 1); }
    }
    if (player.fuel <= 0) gameOver = true;
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Player
    ctx.fillStyle = '#0ff';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.r, 0, Math.PI * 2);
    ctx.fill();
    // Asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // Packages
    ctx.fillStyle = '#ff0';
    packages.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Fuel: ${Math.floor(player.fuel)}`, 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f00';
      ctx.textAlign = 'center';
      ctx.font = '32px sans-serif';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  loop();
})();
